// assets v4: switch icon D
import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Xp, Art } from '../types'

const stats = atom({ plugin: 'codarc', key: 'xp' } as const, null)
const art = atom({ plugin: 'codarc', key: 'art' } as const, null)
const mode = atom({ plugin: 'codarc', key: 'mode' } as const, null)
const celebrate = atom({ plugin: 'codarc', key: 'cel' } as const, null)
const pop = atom({ plugin: 'codarc', key: 'pop' } as const, null)
const pend = atom({ plugin: 'codarc', key: 'pend' } as const, null)

const TITLES: [number, string][] = [
  [1, 'Bronze Spark'], [5, 'Silver Ember'], [10, 'Gold Blaze'],
  [15, 'Crystal Flame'], [20, 'Master Coder'], [30, 'Champion Builder'],
  [40, 'Titan Architect'], [50, 'Legend Blazer'], [75, 'Mythic Legend'], [99, 'Eternal Inferno'],
]

const threshold = (level: number) =>
  level <= 1 ? 0 : Math.round(250 * Math.pow(level - 1, 1.8))

function progress(xp: number) {
  let level = 1
  while (level < 99 && xp >= threshold(level + 1)) level += 1
  const lo = threshold(level)
  const hi = threshold(level + 1)
  const frac = level >= 99 ? 1 : (xp - lo) / (hi - lo)
  let title = TITLES[0]![1]
  for (const [min, t] of TITLES) if (level >= min) title = t
  return { level, frac, title, into: Math.floor(xp - lo), need: hi - lo }
}


