function label(str: string, size: number, x: number, y: number, fill: string, outline = 0) {
  const k = size / 100
  let cx = 0
  let d = ''
  for (const ch of str) {
    const gl = GLYPHS[ch] ?? GLYPHS[' ']!
    if (gl[1]) d += `<path transform="translate(${cx.toFixed(1)} 0)" d="${gl[1]}"/>`
    cx += gl[0] + 2
  }
  return { w: cx * k, svg: `<g transform="translate(${x} ${y}) scale(${k})" fill="${fill}"${outline ? ` stroke="#111111" stroke-width="${outline}" stroke-linejoin="round" paint-order="stroke"` : ''}>${d}</g>` }
}

function width(str: string, size: number) {
  return label(str, size, 0, 0, '#000').w
}

// Like label(), but each glyph is defined once (see glyphDefs) and drawn with <use>,
// so long lists stay under the Svg size limit.
const usedGlyphs = new Set<string>()
function labelUse(str: string, size: number, x: number, y: number, fill: string, outline = 0) {
  const k = size / 100
  let cx = 0
  let d = ''
  for (const ch of str) {
    const gl = GLYPHS[ch] ?? GLYPHS[' ']!
    if (gl[1]) {
      usedGlyphs.add(ch)
      d += `<use href="#g${ch.charCodeAt(0)}" x="${cx.toFixed(1)}"/>`
    }
    cx += gl[0] + 2
  }
  const st = outline ? ` stroke="#111111" stroke-width="${outline}" stroke-linejoin="round" paint-order="stroke"` : ''
  return `<g transform="translate(${x} ${y}) scale(${k})" fill="${fill}"${st}>${d}</g>`
}

function glyphDefs() {
  let d = ''
  for (const ch of usedGlyphs) d += `<path id="g${ch.charCodeAt(0)}" d="${GLYPHS[ch]![1]}"/>`
  return `<defs>${d}</defs>`
}

// Estimated on-site cooling water per dollar of Claude spend: ~75 Wh per dollar
// (Couch, Jan 2026, from Claude Code token mix) x ~1.1 mL per Wh (Google, Aug 2025:
// 0.26 mL for 0.24 Wh). Counting power-station water would be about 4x higher.
const WATER_ML_PER_USD = 80

function waterText(usd: number) {
  const ml = usd * WATER_ML_PER_USD
  return ml >= 1000 ? `~${(ml / 1000).toFixed(1)} L` : `~${Math.round(ml)} mL`
}

// ---- Tier badges (rounded, faceted, one per title; index matches TITLES) ----
type Tier = { n: number; base: string; inner: string; rb?: string[]; rim?: string; wl?: number; wk?: number; wc?: string; glow?: string; sp?: number[][]; gem?: boolean }
const RAINBOW = ['#ff8ad0', '#ffd36e', '#8fe9ff', '#c89bff', '#ff9a8a', '#8dffc2']
const TIER_ART: Tier[] = [
  { n: 5, base: '#8a5a3a', inner: '#d9904f' },
  { n: 5, base: '#aab6c4', inner: '#cfe0f2' },
  { n: 5, base: '#e0a336', inner: '#f9cf62' },
  { n: 6, base: '#4a7be8', inner: '#46d6c0', wl: 14, wk: 3, wc: '#6fa0ff' },
  { n: 6, base: '#6c7bea', inner: '#dcd8ff', rim: '#e3a73a', wl: 18, wk: 4, wc: '#bcd4f5', sp: [[96, 44, 5]] },
  { n: 6, base: '#6a4fd8', inner: '#b38cff', rim: '#e3a73a', wl: 22, wk: 4, wc: '#f0b84a', sp: [[14, 40, 4], [100, 36, 5]] },
  { n: 6, base: '#d83a3a', inner: '#ffb347', rim: '#e3a73a', wl: 26, wk: 4, wc: '#f0b84a', glow: '#ff7a45', sp: [[12, 30, 5], [104, 34, 5], [16, 92, 3]] },
  { n: 6, base: '#5fae1c', inner: '#c8ff3d', rim: '#e3a73a', wl: 28, wk: 5, wc: '#f0b84a', glow: '#c8ff3d', sp: [[10, 28, 5], [106, 26, 5], [100, 96, 3]] },
  { n: 6, base: '#b840d6', inner: '#ff9bd9', rb: RAINBOW, rim: '#e3a73a', wl: 30, wk: 5, wc: '#e8b8ff', glow: '#e070ff', sp: [[8, 26, 6], [108, 24, 6], [14, 96, 4]] },
  { n: 6, base: '#d63a4a', inner: '#ffcf8a', rb: RAINBOW, rim: '#f0b84a', wl: 32, wk: 5, wc: '#ffd6a0', glow: '#ff7a45', gem: true, sp: [[6, 24, 6], [110, 22, 6], [12, 98, 4], [108, 96, 4], [88, 10, 4]] },
]

function tierIndex(level: number) {
  let idx = 0
  TITLES.forEach(([min], i) => { if (level >= min) idx = i })
  return idx
}

function hx(c: string) {
  return [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)]
}
function mix(a: string, b: string, t: number) {
  const x = hx(a)
  const y = hx(b)
  return '#' + [0, 1, 2].map((i) => {
    const v = Math.round(x[i]! + (y[i]! - x[i]!) * t)
    return ('0' + Math.max(0, Math.min(255, v)).toString(16)).slice(-2)
  }).join('')
}
function shade(base: string, ang: number) {
  const l = Math.cos(ang + 2.356)
  return l > 0 ? mix(base, '#ffffff', l * 0.5) : mix(base, '#000000', -l * 0.5)
}
type Pt = number[]
function ngon(n: number, r: number, i: number): Pt {
  const a = ((-90 + (360 / n) * i) * Math.PI) / 180
  return [60 + Math.cos(a) * r, 64 + Math.sin(a) * r]
}
function pts(a: Pt[]) {
  return a.map((p) => `${p[0]!.toFixed(1)},${p[1]!.toFixed(1)}`).join(' ')
}
function rp(P: Pt[], r: number) {
  const n = P.length
  let d = ''
  for (let i = 0; i < n; i++) {
    const p0 = P[(i - 1 + n) % n]!
    const p1 = P[i]!
    const p2 = P[(i + 1) % n]!
    const v1 = [p0[0]! - p1[0]!, p0[1]! - p1[1]!]
    const v2 = [p2[0]! - p1[0]!, p2[1]! - p1[1]!]
    const l1 = Math.hypot(v1[0]!, v1[1]!)
    const l2 = Math.hypot(v2[0]!, v2[1]!)
    const k1 = Math.min(r, l1 / 2) / l1
    const k2 = Math.min(r, l2 / 2) / l2
    const a = [p1[0]! + v1[0]! * k1, p1[1]! + v1[1]! * k1]
    const b = [p1[0]! + v2[0]! * k2, p1[1]! + v2[1]! * k2]
    d += `${i ? 'L' : 'M'}${a[0]!.toFixed(1)} ${a[1]!.toFixed(1)}Q${p1[0]!.toFixed(1)} ${p1[1]!.toFixed(1)} ${b[0]!.toFixed(1)} ${b[1]!.toFixed(1)}`
  }
  return d + 'Z'
}
function spark(x: number, y: number, s: number) {
  const e = s * 0.18
  return `<path d="M${x} ${y - s}Q${x + e} ${y - e} ${x + s} ${y}Q${x + e} ${y + e} ${x} ${y + s}Q${x - e} ${y + e} ${x - s} ${y}Q${x - e} ${y - e} ${x} ${y - s}Z" fill="#fff" stroke="#fff" stroke-width="1.2" stroke-linejoin="round" opacity=".95"/>`
}
function wingSet(o: Tier, sg: number) {
  let s = ''
  const L = o.wl ?? 0
  const k = o.wk ?? 0
  for (let i = 0; i < k; i++) {
    const bx = 60 + sg * 43
    const by = 52 + i * 9 - k * 2
    const tx = bx + sg * (L - i * 3.5)
    const ty = by - 12 + i * 7
    s += `<path d="${rp([[bx, by - 6], [tx, ty], [bx, by + 7]], 5)}" fill="${mix(o.wc ?? '#ffffff', i % 2 ? '#000000' : '#ffffff', 0.18)}" stroke="${mix(o.wc ?? '#ffffff', '#000000', 0.5)}" stroke-width="1.2" stroke-linejoin="round"/>`
  }
  return s
}

const SIGIL = 'M47 8L24 42L18 64L32 88L47 95L47 72L36 58L47 36Z M53 17L76 46L82 66L68 86L53 90L53 70L64 58L53 40Z M50 38L55 50L50 62L45 50Z'

function badgeBody(index: number) {
  const o = TIER_ART[index] ?? TIER_ART[0]!
  const n = o.n
  const idx = [0, 1, 2, 3, 4, 5].slice(0, n)
  const R = 48
  const r1 = 38
  const r2 = 31
  let s = ''
  if (o.glow) s += `<circle cx="60" cy="64" r="58" fill="${o.glow}" opacity=".22"/><circle cx="60" cy="64" r="50" fill="${o.glow}" opacity=".18"/>`
  if (o.wl) s += wingSet(o, -1) + wingSet(o, 1)
  if (o.rim) s += `<path d="${rp(idx.map((i) => ngon(n, 53, i)), 11)}" fill="${o.rim}" stroke="#5a3d10" stroke-width="1.6" stroke-linejoin="round"/>`
  const sil = rp(idx.map((i) => ngon(n, R, i)), 10)
  const ring = rp(idx.map((i) => ngon(n, r1, i)), 7)
  const inn = rp(idx.map((i) => ngon(n, r2, i)), 6)
  s += `<defs><clipPath id="s"><path d="${sil}"/></clipPath><clipPath id="i"><path d="${inn}"/></clipPath></defs><g clip-path="url(#s)">`
  for (let i = 0; i < n; i++) {
    const a = ((-90 + (360 / n) * (i + 0.5)) * Math.PI) / 180
    s += `<polygon points="${pts([ngon(n, R + 6, i), ngon(n, R + 6, i + 1), ngon(n, r1, i + 1), ngon(n, r1, i)])}" fill="${shade(o.base, a)}"/>`
  }
  s += `</g><path d="${sil}" fill="none" stroke="${mix(o.base, '#000000', 0.6)}" stroke-width="1.4" stroke-linejoin="round"/>`
  s += `<path d="${ring}" fill="${mix(o.base, '#000000', 0.7)}"/><g clip-path="url(#i)">`
  for (let i = 0; i < n; i++) {
    const a = ((-90 + (360 / n) * (i + 0.5)) * Math.PI) / 180
    const f = o.rb ? o.rb[i % o.rb.length]! : shade(o.inner, a)
    s += `<polygon points="${pts([[60, 64], ngon(n, r2 + 4, i), ngon(n, r2 + 4, i + 1)])}" fill="${f}"/>`
  }
  s += `</g><path d="${inn}" fill="none" stroke="${mix(o.inner, '#000000', 0.35)}" stroke-width=".9" stroke-linejoin="round"/>`
  s += `<g transform="translate(39 42.2) scale(.42)" opacity=".34"><path d="${SIGIL}" fill="#fff" stroke="#fff" stroke-width="7" stroke-linejoin="round"/></g>`
  for (const p of o.sp ?? []) s += spark(p[0]!, p[1]!, p[2]!)
  if (o.gem) s += `<path d="${rp([[60, 0], [68, 9], [60, 18], [52, 9]], 3.5)}" fill="#ff7bd0" stroke="#5a3d10" stroke-width="1.6" stroke-linejoin="round"/><path d="${rp([[60, 3.5], [64, 9], [60, 14.5], [56, 9]], 2)}" fill="#ffd6f2"/>`
  return s
}

function badgeSvg(index: number) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-4 -2 128 124">${badgeBody(index)}</svg>`
}

function dayStr(d: Date) {
  const m = String(d.getMonth() + 1).padStart(2, '0')
  const dd = String(d.getDate()).padStart(2, '0')
  return `${d.getFullYear()}-${m}-${dd}`
}

function prevDay(day: string) {
  const d = new Date(`${day}T12:00:00`)
  d.setDate(d.getDate() - 1)
  return dayStr(d)
}

// Same rule as xp.py touch_day: first work of a day extends or restarts the streak.
function touchDay(st: any, today: string) {
  if (st.last_active === today) return false
  st.streak = st.last_active === prevDay(today) ? (Number(st.streak) || 0) + 1 : 1
  st.best_streak = Math.max(Number(st.best_streak) || 0, st.streak)
  const bonus = 25 + Math.min(50, 5 * (st.streak - 1))
  st.xp = (Number(st.xp) || 0) + bonus
  st.days = st.days ?? {}
  st.days[today] = (Number(st.days[today]) || 0) + bonus
  st.last_active = today
  return true
}


// ---- Verified-XP rules (pure, so they can be tested) ----
type Ev = { k: 'test'; ok: boolean } | { k: 'build' } | { k: 'commit'; h: string } | { k: 'lines'; n: number }
const TEST_RE = /\b(pytest|vitest|jest|mocha|cargo test|go test|swift test|bun test|(npm|yarn|pnpm)( run)? test)\b/
const BUILD_RE = /\b((npm|yarn|pnpm) run (build|lint)|tsc|eslint|ruff|cargo (build|check|clippy)|go build|swift build)\b/
const COMMIT_RE = /\bgit\s+(-\S+\s+)*commit\b/
const SRC_RE = /\.(ts|tsx|js|jsx|py|swift|go|rs|java|kt|c|cc|cpp|h|rb|css|html|sh)$/
const CAPS = { test: 5, fix: 3, commit: 5, build: 3, lines: 60 }

// Turn one finished tool call into zero or more verified events.
function scoreCall(tool: string, input: any, res: any): Ev[] {
  const out: Ev[] = []
  if (!res || res.deny !== undefined) return out
  const failed = res.isError === true
  if (tool === 'Bash') {
    const cmd = String(input?.command ?? '')
    if (cmd.includes('plugin validate')) return out
    const stdout = String(res.result?.stdout ?? res.text ?? '')
    if (COMMIT_RE.test(cmd) && !failed && !/--amend/.test(cmd)) {
      const m = /\[[^\]]*?\s([0-9a-f]{7,40})\]/.exec(stdout)
      if (m) out.push({ k: 'commit', h: m[1]! })
    }
    if (TEST_RE.test(cmd)) out.push({ k: 'test', ok: !failed })
    else if (BUILD_RE.test(cmd) && !failed) out.push({ k: 'build' })
  } else if (tool === 'Edit' || tool === 'Write') {
    const file = String(input?.file_path ?? res.result?.filePath ?? '')
    if (SRC_RE.test(file) && !failed) {
      let n = 0
      for (const h of res.result?.structuredPatch ?? []) for (const l of h.lines ?? []) if (l.startsWith('+') && !l.startsWith('+++')) n++
      if (n === 0 && tool === 'Write') n = String(input?.content ?? '').split('\n').length
      if (n > 0) out.push({ k: 'lines', n })
    }
  }
  return out
}

// Apply events to the save file with daily caps. Returns the XP paid and a short label.
function applyEvents(st: any, evs: Ev[], today: string): { gain: number; msg: string } {
  if (!st.xpd || st.xpd.day !== today) {
    st.xpd = { day: today, test: 0, fix: 0, commit: 0, build: 0, lines: 0, failed: st.xpd?.failed === true }
  }
  const d = st.xpd
  st.commits = st.commits ?? []
  let gain = 0
  const parts: string[] = []
  const pay = (n: number, label: string) => {
    gain += n
    parts.push(`+${n} ${label}`)
  }
  for (const ev of evs) {
    if (ev.k === 'test') {
      if (!ev.ok) d.failed = true
      else {
        if (d.test < CAPS.test) { d.test++; pay(15, 'tests passed') }
        if (d.failed) {
          d.failed = false
          if (d.fix < CAPS.fix) { d.fix++; pay(25, 'bug fixed') }
        }
      }
    } else if (ev.k === 'build') {
      if (d.build < CAPS.build) { d.build++; pay(8, 'build ok') }
    } else if (ev.k === 'commit') {
      if (!st.commits.includes(ev.h)) {
        st.commits.push(ev.h)
        if (st.commits.length > 200) st.commits.shift()
        if (d.commit < CAPS.commit) { d.commit++; pay(20, 'commit') }
      }
    } else if (ev.k === 'lines') {
      const before = Math.floor(d.lines)
      d.lines = Math.min(CAPS.lines, d.lines + ev.n * 0.2)
      const n = Math.floor(d.lines) - before
      if (n > 0) { gain += n; parts.push(`+${n} code`) }
    }
  }
  gain = Math.round(gain)
  if (gain > 0) {
    st.xp = (Number(st.xp) || 0) + gain
    st.days = st.days ?? {}
    st.days[today] = (Number(st.days[today]) || 0) + gain
  }
  return { gain, msg: parts.join('  ') }
}

export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    try {
      const root = `${$.plugin.root}/assets`
      const a: Art = {
        fire: await $.fs.read(`${root}/flame.svg`),
        firePop: await $.fs.read(`${root}/flame-pop.svg`),
        water: await $.fs.read(`${root}/water.svg`),
        waterPop: await $.fs.read(`${root}/water-pop.svg`),
      }
      await update($, art, () => a)
    } catch {
      await update($, art, () => null)
    }
    await update($, pop, () => false)
    const home = await $.env.get('HOME')
    try {
      const raw = await $.fs.read(`${home}/.claude/xp-hud/state.json`)
      const s = JSON.parse(raw)
      const fresh: Xp = { xp: Number(s.xp) || 0, streak: s.last_active ? Number(s.streak) || 0 : 0, last: s.last_active ?? null, usd: Number(s.lifetime_usd) || 0 }
      await update($, stats, () => fresh)
    } catch {
      await update($, stats, () => null)
    }
    return next(e)
  })

  // First time a skill is ever used: record it, pay a bonus, play a celebration.
  on('skill.prompt', async ($, e, next) => {
    try {
      const home = await $.env.get('HOME')
      const file = `${home}/.claude/xp-hud/state.json`
      const st = JSON.parse(await $.fs.read(file))
      st.skills_seen = st.skills_seen ?? {}
      if (!st.skills_seen[e.skill]) {
        const today = dayStr(new Date())
        st.skills_seen[e.skill] = today
        st.xp = (Number(st.xp) || 0) + 30
        st.days = st.days ?? {}
        st.days[today] = (Number(st.days[today]) || 0) + 30
        await $.fs.write(file, JSON.stringify(st, null, 1))
        const fresh: Xp = { xp: Number(st.xp) || 0, streak: st.last_active ? Number(st.streak) || 0 : 0, last: st.last_active ?? null, usd: Number(st.lifetime_usd) || 0 }
        await update($, stats, () => fresh)
        const at = await $.clock.now()
        await update($, celebrate, () => `${at}|${e.skill}`)
      }
    } catch {
      // no save file: skip the reward
    }
    return next(e)
  })

  // Watch finished tool calls and queue verified events; pay them at turn end.
  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    try {
      const evs = scoreCall(String((e as any).tool), e, r)
      if (evs.length > 0) {
        const tt = Number(await $.clock.now())
        const stamped = evs.map((x) => ({ ...x, t: tt }))
        await update($, pend, (cur) => JSON.stringify([...(cur ? JSON.parse(cur) : []), ...stamped]))
      }
    } catch {
      // never disturb the tool call
    }
    return r
  })

  on('turn.complete', async ($, e, next) => {
    await update($, pop, () => false)
    const home = await $.env.get('HOME')
    try {
      const file = `${home}/.claude/xp-hud/state.json`
      const st = JSON.parse(await $.fs.read(file))
      let dirty = touchDay(st, dayStr(new Date()))
      const u = await $.session.usage()
      const usd = u.cost?.usd
      if (typeof usd === 'number') {
        const sid = await $.session.id()
        const now = await $.clock.now()
        st.sessions = st.sessions ?? {}
        let sess = st.sessions[sid]
        if (!sess) {
          sess = { cost: now - u.startedAt < 60000 ? 0 : usd, lines: 0 }
          st.sessions[sid] = sess
        }
        let d = usd - sess.cost
        if (d < 0) d = usd
        d = Math.min(d, 25)
        if (d > 0) st.lifetime_usd = (Number(st.lifetime_usd) || 0) + d
        sess.cost = usd
        sess.seen = now / 1000
        dirty = true
      }
      try {
        const raw: any[] = (await read($, pend)) ? JSON.parse((await read($, pend)) as string) : []
        await update($, pend, () => null)
        // The xp-hud plugin's own hooks pay the same tool calls; skip what they already paid.
        const hk = (Number(st.hook_ts) || 0) * 1000
        const q: Ev[] = raw.filter((x) => !(hk && hk >= (Number(x.t) || 0) - 5000))
        if (q.length > 0) {
          const r = applyEvents(st, q, dayStr(new Date()))
          dirty = true
          if (r.gain > 0) $.ui.toast(r.msg)
        }
      } catch {
        // bad queue: drop it
      }
      if (dirty) await $.fs.write(file, JSON.stringify(st, null, 1))
    } catch {
      // no save file yet: nothing to record
    }
    try {
      const raw = await $.fs.read(`${home}/.claude/xp-hud/state.json`)
      const s = JSON.parse(raw)
      const fresh: Xp = { xp: Number(s.xp) || 0, streak: s.last_active ? Number(s.streak) || 0 : 0, last: s.last_active ?? null, usd: Number(s.lifetime_usd) || 0 }
      await update($, stats, () => fresh)
    } catch {
      await update($, stats, () => null)
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const s = await read($, stats)
    if (e.props.hasSurvey || s === null) return next(e)

    const ui = $.ui.resolve(e)
    const { Box, Button, Text } = ui
    const Svg = (ui as any).Svg
    const arts = await read($, art)
    const m = (await read($, mode)) === 'water' ? 'water' : 'fire'
    const popped = (await read($, pop)) === true
    const celRaw = await read($, celebrate)
    let cel: string | null = null
    if (celRaw !== null) {
      const cut = celRaw.indexOf('|')
      const at = Number(celRaw.slice(0, cut))
      if (Number((await $.clock.now())) - at < 8000) cel = celRaw.slice(cut + 1)
    }
    const mascot = arts === null ? null : m === 'water' ? (popped ? arts.waterPop : arts.water) : (popped ? arts.firePop : arts.fire)
    const p = progress(s.xp)

    const H = 28
    const FS = 17
    const base = 20
    const lvText = `Lv ${p.level}`
    const lvW = width(lvText, FS) + 14
    const lv = label(lvText, FS, 7, base, '#111111')
    const ttl = label(p.title, FS, lvW + 9, base, '#ffffff', 16)
    const leftW = Math.ceil(lvW + 9 + ttl.w + 4)
    const left =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${leftW} ${H}">` +
      `<rect x="1" y="3" width="${lvW}" height="22" rx="6" fill="#c8ff3d" stroke="#111" stroke-width="2"/>` +
      lv.svg + ttl.svg + `</svg>`

    // Hover list: every tier with its badge, current one highlighted.
    const RH = 30
    const curTier = tierIndex(p.level)
    const rows = TITLES.map(([lv, name], k) => {
      const y = 8 + k * RH
      const t = labelUse(name, 15, 42, y + 20, '#ffffff', 14)
      const l = labelUse(`LV ${lv}+`, 12, 196, y + 19, k === curTier ? '#c8ff3d' : '#d9d2ff', 10)
      const bd = badgeBody(k).replace(/id="(\w)"/g, `id="$1${k}"`).replace(/url\(#(\w)\)/g, `url(#$1${k})`)
      return (
        (k === curTier ? `<rect x="4" y="${y - 1}" width="252" height="${RH - 1}" rx="9" fill="#ffffff" fill-opacity="0.16" stroke="#c8ff3d" stroke-width="1.5"/>` : '') +
        `<svg x="8" y="${y}" width="29" height="${RH - 3}" viewBox="-4 -2 128 124">${bd}</svg>` + t + l
      )
    }).join('')
    const listH = 16 + TITLES.length * RH
    const tierList =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 ${listH}">` +
      `<rect x="1.5" y="1.5" width="257" height="${listH - 3}" rx="14" fill="#2b1f78" stroke="#c8ff3d" stroke-width="3"/>` +
      glyphDefs() + rows + `</svg>`

    // Switch icon: flame and drop swapping places, on a lime-rimmed chip.
    const swapIcon =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 90">` +
      `<rect x="4" y="8" width="112" height="74" rx="22" fill="#2b1f78" stroke="#c8ff3d" stroke-width="5"/>` +
      `<path d="M32 64C17 64 17 44 32 26C32 40 46 40 46 53C46 60 41 64 32 64Z" fill="#f19a33" stroke="#111" stroke-width="3.5" stroke-linejoin="round"/>` +
      `<path d="M90 24C102 42 108 50 98 62C88 70 74 62 76 52C76 45 84 38 90 24Z" fill="#58b6f7" stroke="#111" stroke-width="3.5" stroke-linejoin="round"/>` +
      `<path d="M50 40H70M50 52H70" stroke="#c8ff3d" stroke-width="4" stroke-linecap="round"/>` +
      `<path d="M68 34L76 40L68 46ZM52 46L44 52L52 58Z" fill="#c8ff3d" stroke="#c8ff3d" stroke-width="2" stroke-linejoin="round"/>` +
      `</svg>`

    const BW = 100
    const fw = Math.round(p.frac * (BW - 6))
    const xpText = `${p.into}/${p.need} XP`
    const XS = 13
    const xp = label(xpText, XS, BW + 9, base - 2, '#111111')
    const midW = Math.ceil(BW + 9 + xp.w + 4)
    const midInner =
      `<rect x="1" y="8" width="${BW}" height="12" rx="6" fill="#6b57d6" stroke="#111" stroke-width="2"/>` +
      `<clipPath id="b"><rect x="4" y="11" width="${BW - 6}" height="6" rx="3"/></clipPath>` +
      `<g clip-path="url(#b)"><rect x="4" y="11" width="${fw}" height="6" fill="#c8ff3d"/><rect x="4" y="11" width="${fw}" height="2" fill="#e6ff8a"/></g>` +
      xp.svg
    const barOnly =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${BW + 2} ${H}">` +
      `<rect x="1" y="8" width="${BW}" height="12" rx="6" fill="#6b57d6" stroke="#111" stroke-width="2"/>` +
      `<clipPath id="b"><rect x="4" y="11" width="${BW - 6}" height="6" rx="3"/></clipPath>` +
      `<g clip-path="url(#b)"><rect x="4" y="11" width="${fw}" height="6" fill="#c8ff3d"/><rect x="4" y="11" width="${fw}" height="2" fill="#e6ff8a"/></g></svg>`
    const BX = 20
    const BW2 = 150
    const BH = 40
    const XS2 = 14
    const fw2 = Math.round(p.frac * (BW2 - 6))
    const numW = width(xpText, XS2)
    const num = label(xpText, XS2, BX + (BW2 - numW) / 2, 25, '#ffffff', 14)
    const xpBar =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${BX + BW2 + 2} ${BH}">` +
      `<rect x="${BX}" y="10" width="${BW2}" height="20" rx="10" fill="#4a3bb0" stroke="#111" stroke-width="2.5"/>` +
      `<clipPath id="b"><rect x="${BX + 3}" y="13" width="${BW2 - 6}" height="14" rx="7"/></clipPath>` +
      `<g clip-path="url(#b)"><rect x="${BX + 3}" y="13" width="${fw2}" height="14" fill="#c8ff3d"/><rect x="${BX + 3}" y="13" width="${fw2}" height="4" fill="#e6ff8a"/></g>` +
      num.svg +
      `<svg x="0" y="0" width="41" height="40" viewBox="-4 -2 128 124">${badgeBody(tierIndex(p.level))}</svg></svg>`
    const xpOnly = label(xpText, XS, 2, base - 2, '#111111')
    const xpW = Math.ceil(xpOnly.w + 6)
    const xpSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${xpW} ${H}">${xpOnly.svg}</svg>`
    let mid = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${midW} ${H}">${midInner}</svg>`
    let midWidth = midW
    if (cel !== null) {
      const FB = 15
      const bText = `NEW SKILL! ${cel} +30 XP`
      const bl = label(bText, FB, 12, 19, '#111111')
      const bw = Math.ceil(bl.w + 24)
      const W = Math.max(midW, bw)
      const star = (cx: number, cy: number, d: string) =>
        `<g transform="translate(${cx} ${cy})"><path d="M0 -9 L2.5 -2.5 L9 0 L2.5 2.5 L0 9 L-2.5 2.5 L-9 0 L-2.5 -2.5 Z" fill="#c8ff3d" stroke="#111" stroke-width="1.5" stroke-linejoin="round" transform="scale(0)">` +
        `<animateTransform attributeName="transform" type="scale" values="0;1.3;0" dur="0.9s" begin="${d}s" repeatCount="4" additive="replace"/></path></g>`
      const stars = [0.06, 0.2, 0.36, 0.5, 0.66, 0.8, 0.94].map((f, i) => star(Math.round(f * W), i % 2 ? 6 : 22, (i * 0.17).toFixed(2))).join('')
      mid =
        `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}">` +
        `<g transform="translate(${W / 2} 14)"><g><animateTransform attributeName="transform" type="scale" values="0 0;1.25 .8;.92 1.1;1 1" keyTimes="0;.4;.7;1" dur="0.6s" fill="freeze"/>` +
        `<g transform="translate(${-bw / 2} -14)"><g><animate attributeName="opacity" values="1;1;0" keyTimes="0;.92;1" dur="6s" fill="freeze"/>` +
        `<rect x="1" y="3" width="${bw - 2}" height="22" rx="8" fill="#c8ff3d" stroke="#111" stroke-width="2"/>${bl.svg}</g></g></g></g>` +
        stars +
        `<g opacity="0"><animate attributeName="opacity" values="0;0;1" keyTimes="0;.92;1" dur="6s" fill="freeze"/><g transform="translate(${(W - midW) / 2} 0)">${midInner}</g></g></svg>`
      midWidth = W
    }

    const todayS = dayStr(new Date())
    const live = s.last === todayS || s.last === prevDay(todayS) ? s.streak : 0
    const dTxt = m === 'water' ? waterText(s.usd) : `${live}d`
    const dW = width(dTxt, FS) + 14
    const dl = label(dTxt, FS, 7, base, '#111111')
    const streak =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.ceil(dW + 3)} ${H}">` +
      `<rect x="1" y="3" width="${dW}" height="22" rx="6" fill="#c8ff3d" stroke="#111" stroke-width="2"/>` + dl.svg + `</svg>`

    return (
      <Box backgroundColor="#a99bff" borderStyle="round" borderColor="#c8ff3d" width="100%" flexGrow={1} alignItems="center" paddingX={1} paddingY={0}>
        {Svg ? (
          <Box key="tiers" position="relative">
            <Svg source={left} alt={`Level ${p.level} ${p.title}`} width={leftW} height={H} isInteractive />
            <Box position="absolute" bottom={H} left={0} display="none" hover={{ display: 'flex' }}>
              <Svg source={tierList} alt="All tiers" width={260} height={listH} />
            </Box>
          </Box>
        ) : null}
        <Box flexGrow={1} />
        {Svg && cel !== null ? <Svg source={mid} alt={`${p.into} of ${p.need} XP`} width={midWidth} height={H} /> : null}
        {Svg && cel === null ? <Svg source={xpBar} alt={`${p.into} of ${p.need} XP`} width={BX + BW2 + 2} height={BH} /> : null}
        <Box flexGrow={1} />
        <Box key="right" position="relative" flexDirection="row" alignItems="center">
          {Svg && mascot !== null ? <Svg source={mascot} alt={m === 'water' ? 'Water mascot' : 'Fire mascot'} width={20} height={21} isInteractive /> : null}
          {Svg ? <Svg source={streak} alt={m === 'water' ? `Estimated water used: ${dTxt}` : `${live} day streak`} width={Math.ceil(dW + 3)} height={H} isInteractive /> : null}
          <Box position="absolute" top={0} left={0} display="none" hover={{ display: 'flex' }}>
            <Box position="relative">
              <Svg source={swapIcon} alt="Switch fire and water" width={36} height={27} />
              <Box position="absolute" top={0} left={0}>
                <Button
                  key="mascot-toggle"
                  plain
                  onPress={async () => {
                    await update($, mode, (v) => (v === 'water' ? 'fire' : 'water'))
                    await update($, pop, () => true)
                  }}
                >
                  <Text>{'     '}</Text>
                </Button>
              </Box>
            </Box>
          </Box>
        </Box>
      </Box>
    )
  })
}
